#!/bin/sh
# Copy the EControl lexer library (lib.lxl) next to the built binary.
#
# MDPad loads lib.lxl at startup (see FormCreate) to get ATSynEdit's syntax
# highlighting and code tree. Without it the editor still works, but every file
# shows up as plain text. The file is generated by ATSynEdit's lexlib tool and
# is not part of the MDPad sources.
#
# Source : $ATSYNEDIT_DIR/app/lexlib/lib.lxl
#          (ATSYNEDIT_DIR defaults to $HOME/projects/components/ATSynEdit)
# Targets: every lib/<cpu>-<os>/ output directory, plus the project root
#          (where the Release build writes its binary).
#
# Wired as the "Execute after" command in MarkDownPad.lpi. It must never fail
# the build: a missing source prints a note and exits 0.

set -u

projdir=$(cd "$(dirname "$0")/.." && pwd)
srcdir=${ATSYNEDIT_DIR:-$HOME/projects/components/ATSynEdit}
src=$srcdir/app/lexlib/lib.lxl

if [ ! -f "$src" ]; then
  echo "copy-lexlib: $src not found, skipping (override with ATSYNEDIT_DIR)"
  exit 0
fi

copied=0
for d in "$projdir" "$projdir"/lib/*/; do
  [ -d "$d" ] || continue
  cp -f "$src" "$d/lib.lxl" && copied=$((copied + 1))
done

echo "copy-lexlib: lib.lxl -> $copied output dir(s)"
